    },
    "text": "Rapid consecutive NFC punches for same card_id must not create duplicate attendance records.",
    "assertion": "forall rapid_punches(card_id, window<2s): only one attendance record created per toggle",
    "covers": "SG-001",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

